import{_ as i,o as s,c as e,a2 as r}from"./chunks/framework.EUByU7Iq.js";const n=JSON.parse('{"title":"《飞鸟集 · 郑振铎译》","description":"","frontmatter":{"title":"《飞鸟集 · 郑振铎译》","date":"2026-11-19T00:00:00.000Z","categories":["美文","飞鸟集"],"collection":"《飞鸟集 · 郑振铎译》","tags":["飞鸟集","印度"],"poem":true,"poem_quote":false,"merged":true,"pieces":54,"author":"泰戈尔","source_book":"飞鸟集"},"headers":[],"relativePath":"blogs/飞鸟集·郑振铎译/index.md","filePath":"blogs/飞鸟集·郑振铎译/index.md"}'),t={name:"blogs/飞鸟集·郑振铎译/index.md"};function o(l,a,h,d,p,c){return s(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="《飞鸟集-·-郑振铎译》" tabindex="-1">《飞鸟集 · 郑振铎译》 <a class="header-anchor" href="#《飞鸟集-·-郑振铎译》" aria-label="Permalink to &quot;《飞鸟集 · 郑振铎译》&quot;">​</a></h1><p class="poem-meta">印度 · 泰戈尔（1861—1941）　·　郑振铎译</p><p>全 54 首，收录完整。</p><div class="merged-book"><h3 id="第1首" tabindex="-1">第1首 <a class="header-anchor" href="#第1首" aria-label="Permalink to &quot;第1首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">夏天的飞鸟，飞到我的窗前唱歌，又飞去了。</p><p class="bi-tra">秋天的黄叶，它们没有什么可唱，只叹息一声，飞落在那里。</p><p class="bi-org">Stray birds of summer come to my window to sing and fly away.</p><p class="bi-org">And yellow leaves of autumn, which have no songs, flutter and fall there with a sigh.</p></div></div><h3 id="第2首" tabindex="-1">第2首 <a class="header-anchor" href="#第2首" aria-label="Permalink to &quot;第2首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">世界上的一队小小的漂泊者呀，请留下你们的足印在我的文字里。</p><p class="bi-org">O troupe of little vagrants of the world, leave your footprints in my words.</p></div></div><h3 id="第3首" tabindex="-1">第3首 <a class="header-anchor" href="#第3首" aria-label="Permalink to &quot;第3首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">世界对着它的爱人，把它浩翰的面具揭下了。</p><p class="bi-tra">它变小了，小如一首歌，小如一回永恒的接吻。</p><p class="bi-org">The world puts off its mask of vastness to its lover.</p><p class="bi-org">It becomes small as one song, as one kiss of the eternal.</p></div></div><h3 id="第4首" tabindex="-1">第4首 <a class="header-anchor" href="#第4首" aria-label="Permalink to &quot;第4首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">是大地的泪点，使她的微笑保持着青春不谢。</p><p class="bi-org">It is the tears of the earth that keep her smiles in bloom.</p></div></div><h3 id="第5首" tabindex="-1">第5首 <a class="header-anchor" href="#第5首" aria-label="Permalink to &quot;第5首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">无垠的沙漠热烈追求一叶绿草的爱，她摇摇头笑着飞开了。</p><p class="bi-org">The mighty desert is burning for the love of a blade of grass who shakes her head and laughs and flies away.</p></div></div><h3 id="第6首" tabindex="-1">第6首 <a class="header-anchor" href="#第6首" aria-label="Permalink to &quot;第6首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">如果你因失去了太阳而流泪，那么你也将失去群星了。</p><p class="bi-org">If you shed tears when you miss the sun, you also miss the stars.</p></div></div><h3 id="第7首" tabindex="-1">第7首 <a class="header-anchor" href="#第7首" aria-label="Permalink to &quot;第7首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">跳舞着的流水呀，在你途中的泥沙，要求你的歌声，你的流动呢。你肯挟瘸足的泥沙而俱下么？</p><p class="bi-org">The sands in your way beg for your song and your movement, dancing water. Will you carry the burden of their lameness?</p></div></div><h3 id="第8首" tabindex="-1">第8首 <a class="header-anchor" href="#第8首" aria-label="Permalink to &quot;第8首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">她的热切的脸，如夜雨似的，搅扰着我的梦魂。</p><p class="bi-org">Her wistful face haunts my dreams like the rain at night.</p></div></div><h3 id="第9首" tabindex="-1">第9首 <a class="header-anchor" href="#第9首" aria-label="Permalink to &quot;第9首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">有一次，我们梦见大家都是不相识的。</p><p class="bi-tra">我们醒了，却知道我们原是相亲相爱的。</p><p class="bi-org">Once we dreamt that we were strangers.</p><p class="bi-org">We wake up to find that we were dear to each other.</p></div></div><h3 id="第10首" tabindex="-1">第10首 <a class="header-anchor" href="#第10首" aria-label="Permalink to &quot;第10首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">忧思在我的心里平静下去，正如暮色降临在寂静的山林中。</p><p class="bi-org">Sorrow is hushed into peace in my heart like the evening among the silent trees.</p></div></div><h3 id="第11首" tabindex="-1">第11首 <a class="header-anchor" href="#第11首" aria-label="Permalink to &quot;第11首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">有些看不见的手，如懒懒的微（风思）的，正在我的心上奏着潺潺的乐声。</p><p class="bi-org">Some unseen fingers, like idle breeze, are playing upon my heart the music of the ripples.</p></div></div><h3 id="第12首" tabindex="-1">第12首 <a class="header-anchor" href="#第12首" aria-label="Permalink to &quot;第12首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">“海水呀，你说的是什么？”</p><p class="bi-tra">“是永恒的疑问。”</p><p class="bi-tra">“天空呀，你回答的话是什么？”</p><p class="bi-tra">“是永恒的沉默。”</p><p class="bi-org">&quot;What language is thine, O sea?&quot;</p><p class="bi-org">&quot;The language of eternal question.&quot;</p><p class="bi-org">&quot;What language is thy answer, O sky?&quot;</p><p class="bi-org">&quot;The language of eternal silence.&quot;</p></div></div><h3 id="第13首" tabindex="-1">第13首 <a class="header-anchor" href="#第13首" aria-label="Permalink to &quot;第13首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">静静地听，我的心呀，听那世界的低语，这是它对你求爱的表示呀。</p><p class="bi-org">Listen, my heart, to the whispers of the world with which it makes love to you.</p></div></div><h3 id="第14首" tabindex="-1">第14首 <a class="header-anchor" href="#第14首" aria-label="Permalink to &quot;第14首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">创造的神秘，有如夜间的黑暗－－是伟大的。而知识的幻影却不过如晨间之雾。</p><p class="bi-org">The mystery of creation is like the darkness of night—it is great. Delusions of knowledge are like the fog of the morning.</p></div></div><h3 id="第15首" tabindex="-1">第15首 <a class="header-anchor" href="#第15首" aria-label="Permalink to &quot;第15首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">不要因为峭壁是高的，便让你的爱情坐在峭壁上。</p><p class="bi-org">Do not seat your love upon a precipice because it is high.</p></div></div><h3 id="第16首" tabindex="-1">第16首 <a class="header-anchor" href="#第16首" aria-label="Permalink to &quot;第16首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我今晨坐在窗前，世界如一个路人似的，停留了一会，向我点点头又走过去了。</p><p class="bi-org">I sit at my window this morning where the world like a passer-by stops for a moment, nods to me and goes.</p></div></div><h3 id="第17首" tabindex="-1">第17首 <a class="header-anchor" href="#第17首" aria-label="Permalink to &quot;第17首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">这些微（风思），是树叶的簌簌之声呀；它们在我的心里欢悦地微语着。</p><p class="bi-org">These little thoughts are the rustle of leaves; they have their whisper of joy in my mind.</p></div></div><h3 id="第18首" tabindex="-1">第18首 <a class="header-anchor" href="#第18首" aria-label="Permalink to &quot;第18首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">你看不见你自己，你所看见的只是你的影子。</p><p class="bi-org">What you are you do not see, what you see is your shadow.</p></div></div><h3 id="第19首" tabindex="-1">第19首 <a class="header-anchor" href="#第19首" aria-label="Permalink to &quot;第19首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">神呀，我的那些愿望真是愚傻呀，它们杂在你的歌声中喧叫着呢。</p><p class="bi-tra">让我只是静听着吧。</p><p class="bi-org">My wishes are fools, they shout across thy songs, my Master.</p><p class="bi-org">Let me but listen.</p></div></div><h3 id="第20首" tabindex="-1">第20首 <a class="header-anchor" href="#第20首" aria-label="Permalink to &quot;第20首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我不能选择那最好的。</p><p class="bi-tra">是那最好的选择我。</p><p class="bi-org">I cannot choose the best.</p><p class="bi-org">The best chooses me.</p></div></div><h3 id="第21首" tabindex="-1">第21首 <a class="header-anchor" href="#第21首" aria-label="Permalink to &quot;第21首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">那些把灯背在背上的人，把他们的影子投到了自己前面。</p><p class="bi-org">They throw their shadows before them who carry their lantern on their back.</p></div></div><h3 id="第22首" tabindex="-1">第22首 <a class="header-anchor" href="#第22首" aria-label="Permalink to &quot;第22首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我的存在，对我是一个永久的神奇，这就是生活。</p><p class="bi-org">That I exist is a perpetual surprise which is life.</p></div></div><h3 id="第23首" tabindex="-1">第23首 <a class="header-anchor" href="#第23首" aria-label="Permalink to &quot;第23首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">“我们萧萧的树叶都有声响回答那风和雨。你是谁呢，那样的沉默着？”</p><p class="bi-tra">“我不过是一朵花。”</p><p class="bi-org">&quot;We, the rustling leaves, have a voice that answers the storms, but who are you so silent?&quot;</p><p class="bi-org">&quot;I am a mere flower.&quot;</p></div></div><h3 id="第24首" tabindex="-1">第24首 <a class="header-anchor" href="#第24首" aria-label="Permalink to &quot;第24首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">休息与工作的关系，正如眼睑与眼睛的关系。</p><p class="bi-org">Rest belongs to the work as the eyelids to the eyes.</p></div></div><h3 id="第25首" tabindex="-1">第25首 <a class="header-anchor" href="#第25首" aria-label="Permalink to &quot;第25首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">人是一个初生的孩子，他的力量，就是生长的力量。</p><p class="bi-org">Man is a born child, his power is the power of growth.</p></div></div><h3 id="第26首" tabindex="-1">第26首 <a class="header-anchor" href="#第26首" aria-label="Permalink to &quot;第26首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">神希望我们酬答他，在于他送给我们的花朵，而不在于太阳和土地。</p><p class="bi-org">God expects answers for the flowers he sends us, not for the sun and the earth.</p></div></div><h3 id="第27首" tabindex="-1">第27首 <a class="header-anchor" href="#第27首" aria-label="Permalink to &quot;第27首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">光明如一个裸体的孩子，快快活活地在绿叶当中游戏，它不知道人是会欺诈的。</p><p class="bi-org">The light that plays, like a naked child, among the green leaves happily knows not that man can lie.</p></div></div><h3 id="第28首" tabindex="-1">第28首 <a class="header-anchor" href="#第28首" aria-label="Permalink to &quot;第28首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">啊，美呀，在爱中找你自己吧，不要到你镜子的谄谀去找寻。</p><p class="bi-org">O Beauty, find thyself in love, not in the flattery of thy mirror.</p></div></div><h3 id="第29首" tabindex="-1">第29首 <a class="header-anchor" href="#第29首" aria-label="Permalink to &quot;第29首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我的心把她的波浪在世界的海岸上冲激着，以热泪在上边写着她的题记：“我爱你。”</p><p class="bi-org">My heart beats her waves at the shore of the world and writes upon it her signature in tears with the words, &quot;I love thee.&quot;</p></div></div><h3 id="第30首" tabindex="-1">第30首 <a class="header-anchor" href="#第30首" aria-label="Permalink to &quot;第30首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">“月儿呀，你在等候什么呢？”</p><p class="bi-tra">“向我将让位给他的太阳致敬。”</p><p class="bi-org">&quot;Moon, for what do you wait?&quot;</p><p class="bi-org">&quot;To salute the sun for whom I must make way.&quot;</p></div></div><h3 id="第31首" tabindex="-1">第31首 <a class="header-anchor" href="#第31首" aria-label="Permalink to &quot;第31首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">绿树长到了我的窗前，仿佛是喑哑的大地发出的渴望的声音。</p><p class="bi-org">The trees come up to my window like the yearning voice of the dumb earth.</p></div></div><h3 id="第32首" tabindex="-1">第32首 <a class="header-anchor" href="#第32首" aria-label="Permalink to &quot;第32首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">神自己的清晨，在他自己看来也是新奇的。</p><p class="bi-org">His own mornings are new surprises to God.</p></div></div><h3 id="第33首" tabindex="-1">第33首 <a class="header-anchor" href="#第33首" aria-label="Permalink to &quot;第33首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">生命从世界得到资产，爱情使它得到价值。</p><p class="bi-org">Life finds its wealth by the claims of the world, and its worth by the claims of love.</p></div></div><h3 id="第34首" tabindex="-1">第34首 <a class="header-anchor" href="#第34首" aria-label="Permalink to &quot;第34首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">枯竭的河床，并不感谢它的过去。</p><p class="bi-org">The dry river-bed finds no thanks for its past.</p></div></div><h3 id="第35首" tabindex="-1">第35首 <a class="header-anchor" href="#第35首" aria-label="Permalink to &quot;第35首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">鸟儿愿为一朵云。</p><p class="bi-tra">云儿愿为一只鸟。</p><p class="bi-org">The bird wishes it were a cloud.</p><p class="bi-org">The cloud wishes it were a bird.</p></div></div><h3 id="第36首" tabindex="-1">第36首 <a class="header-anchor" href="#第36首" aria-label="Permalink to &quot;第36首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">瀑布歌唱道：“我得到自由时便有了歌声了。”</p><p class="bi-org">The waterfall sings, &quot;I find my song, when I find my freedom.&quot;</p></div></div><h3 id="第37首" tabindex="-1">第37首 <a class="header-anchor" href="#第37首" aria-label="Permalink to &quot;第37首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我说不出这心为什么那样默默地颓丧着。</p><p class="bi-tra">是为了它那不曾要求，不曾知道，不曾记得的小小的需要。</p><p class="bi-org">I cannot tell why this heart languishes in silence.</p><p class="bi-org">It is for small needs it never asks, or knows or remembers.</p></div></div><h3 id="第38首" tabindex="-1">第38首 <a class="header-anchor" href="#第38首" aria-label="Permalink to &quot;第38首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">妇人，你在料理家务的时候，你的手足歌唱着，正如山间的溪水歌唱着在小石中流过。</p><p class="bi-org">Woman, when you move about in your household service your limbs sing like a hill stream among its pebbles.</p></div></div><h3 id="第39首" tabindex="-1">第39首 <a class="header-anchor" href="#第39首" aria-label="Permalink to &quot;第39首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">当太阳横过西方的海面时，对着东方留下他的最后的敬礼。</p><p class="bi-org">The sun goes to cross the Western sea, leaving its last salutation to the East.</p></div></div><h3 id="第40首" tabindex="-1">第40首 <a class="header-anchor" href="#第40首" aria-label="Permalink to &quot;第40首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">不要因为你自己没有胃口而去责备你的食物。</p><p class="bi-org">Do not blame your food because you have no appetite.</p></div></div><h3 id="第41首" tabindex="-1">第41首 <a class="header-anchor" href="#第41首" aria-label="Permalink to &quot;第41首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">群树如表示大地的愿望似的，踮起脚来向天空窥望。</p><p class="bi-org">The trees, like the longings of the earth, stand a-tiptoe to peep at the heaven.</p></div></div><h3 id="第42首" tabindex="-1">第42首 <a class="header-anchor" href="#第42首" aria-label="Permalink to &quot;第42首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">你微微地笑着，不同我说什么话。而我觉得，为了这个，我已等待得久了。</p><p class="bi-org">You smiled and talked to me of nothing and I felt that for this I had been waiting long.</p></div></div><h3 id="第43首" tabindex="-1">第43首 <a class="header-anchor" href="#第43首" aria-label="Permalink to &quot;第43首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">水里的游鱼是沉默的，陆地上的兽类是喧闹的，空中的飞鸟是歌唱着的。</p><p class="bi-tra">但是，人类却兼有海里的沉默，地上的喧闹与空中的音乐。</p><p class="bi-org">The fish in the water is silent, the animal on the earth is noisy, the bird in the air is singing,</p><p class="bi-org">But Man has in him the silence of the sea, the noise of the earth and the music of the air.</p></div></div><h3 id="第44首" tabindex="-1">第44首 <a class="header-anchor" href="#第44首" aria-label="Permalink to &quot;第44首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">世界在踌躇之心的琴弦上跑过去，奏出忧郁的乐声。</p><p class="bi-org">The world rushes on over the strings of the lingering heart making the music of sadness.</p></div></div><h3 id="第45首" tabindex="-1">第45首 <a class="header-anchor" href="#第45首" aria-label="Permalink to &quot;第45首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">他把他的刀剑当作他的上帝。</p><p class="bi-tra">当他的刀剑胜利的时候他自己却失败了。</p><p class="bi-org">He has made his weapons his gods.</p><p class="bi-org">When his weapons win he is defeated himself.</p></div></div><h3 id="第46首" tabindex="-1">第46首 <a class="header-anchor" href="#第46首" aria-label="Permalink to &quot;第46首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">神从创造中找到他自己。</p><p class="bi-org">God finds himself by creating.</p></div></div><h3 id="第47首" tabindex="-1">第47首 <a class="header-anchor" href="#第47首" aria-label="Permalink to &quot;第47首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">阴影戴上她的面幕，秘密地，温顺地，用她的沉默的爱的脚步，跟在“光”后边。</p><p class="bi-org">Shadow, with her veil drawn, follows Light in secret meekness, with her silent steps of love.</p></div></div><h3 id="第48首" tabindex="-1">第48首 <a class="header-anchor" href="#第48首" aria-label="Permalink to &quot;第48首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">群星不怕显得象萤火那样。</p><p class="bi-org">The stars are not afraid to appear like fireflies.</p></div></div><h3 id="第49首" tabindex="-1">第49首 <a class="header-anchor" href="#第49首" aria-label="Permalink to &quot;第49首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">谢谢神，我不是一个权力的轮子，而是被压在这轮子下的活人之一。</p><p class="bi-org">I thank thee that I am none of the wheels of power but I am one with the living creatures that are crushed by it.</p></div></div><h3 id="第50首" tabindex="-1">第50首 <a class="header-anchor" href="#第50首" aria-label="Permalink to &quot;第50首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">心是尖锐的，不是宽博的，它执着在每一点上，却并不活动。</p><p class="bi-org">The mind, sharp but not broad, sticks at every point but does not move.</p></div></div><h3 id="第51首" tabindex="-1">第51首 <a class="header-anchor" href="#第51首" aria-label="Permalink to &quot;第51首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">你的偶像委散在尘土中了，这可证明神的尘土比你的偶像还伟大。</p><p class="bi-org">Your idol is shattered in the dust to prove that God&#39;s dust is greater than your idol.</p></div></div><h3 id="第52首" tabindex="-1">第52首 <a class="header-anchor" href="#第52首" aria-label="Permalink to &quot;第52首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">人在他的历史中表现不出他自己，他在历史中奋斗着露出头角。</p><p class="bi-org">Man does not reveal himself in his history, he struggles up through it.</p></div></div><h3 id="第53首" tabindex="-1">第53首 <a class="header-anchor" href="#第53首" aria-label="Permalink to &quot;第53首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">玻璃灯因为瓦灯叫它做表兄而责备瓦灯，但当明月出来时，玻璃灯却温和地笑着，叫明月为——“我亲爱的，亲爱的姐姐。”</p><p class="bi-org">While the glass lamp rebukes the earthen for calling it cousin, the moon rises, and the glass lamp, with a bland smile, calls her,—&quot;My dear, dear sister.&quot;</p></div></div><h3 id="第54首" tabindex="-1">第54首 <a class="header-anchor" href="#第54首" aria-label="Permalink to &quot;第54首&quot;">​</a></h3><div class="poem bi"><div class="bi-pair"><p class="bi-tra">我们如海鸥之与波涛相遇似的，遇见了，走近了。</p><p class="bi-tra">海鸥飞去，波涛滚滚地流开，我们也分别了。</p><p class="bi-org">Like the meeting of the seagulls and the waves we meet and come near. The seagulls fly off, the waves roll away and we depart.</p></div></div></div>',4)])])}const v=i(t,[["render",o]]);export{n as __pageData,v as default};
